<?php
$uid = (int)$u['id'];
handle('profile', function () use ($uid) { $n = trim((string)$_POST['name']); $ph = trim((string)$_POST['phone']); if (mb_strlen($n) < 2) throw new AppError('Enter your name.'); if ($ph !== '' && !preg_match('/^\+?\d{8,15}$/', $ph)) throw new AppError('Phone must be 8-15 digits.'); if ($ph !== '' && val('SELECT 1 FROM users WHERE phone=? AND id<>?', [$ph, $uid])) throw new AppError('That phone number is already used.'); q('UPDATE users SET name=?, phone=? WHERE id=?', [mb_substr($n, 0, 100), $ph === '' ? null : $ph, $uid]); return 'Profile saved.'; });
handle('prefs', function () use ($uid) { q('UPDATE user_settings SET language=?, hide_balance=?, notify_login=?, notify_transaction=?, notify_reminder=?, sim_biometric=? WHERE user_id=?', [$_POST['language'] === 'bn' ? 'bn' : 'en', (int)isset($_POST['hide_balance']), (int)isset($_POST['n_login']), (int)isset($_POST['n_tx']), (int)isset($_POST['n_rem']), (int)isset($_POST['bio']), $uid]); $_SESSION['lang'] = $_POST['language'] === 'bn' ? 'bn' : 'en'; return 'Preferences saved.'; });
$cb = fn($n, $l, $on, $h = '') => '<div class="field"><label style="font-weight:600"><input type="checkbox" name="' . $n . '" value="1"' . ($on ? ' checked' : '') . '> ' . e(t($l)) . '</label>' . ($h ? '<div class="hint">' . e($h) . '</div>' : '') . '</div>';
echo page_head('Settings', 'Profile, language, privacy and notification preferences.') . '<div class="grid g2">' . card('Profile', form_start('profile') . field('Full name', 'name', 'text', $u['name'], 'required maxlength="100"') . field('Email', 'email', 'email', $u['email'], 'disabled', 'Email cannot be changed in this demo.') . field('Phone', 'phone', 'tel', (string)val('SELECT phone FROM users WHERE id=?', [$uid]), 'placeholder="+8801XXXXXXXXX"') . btn('Save changes') . '</form>') .
  card('Preferences and privacy', form_start('prefs') . select('Language', 'language', ['en' => 'English', 'bn' => 'বাংলা (Bangla)'], $u['language']) . $cb('hide_balance', 'Hide balances', (int)$u['hide_balance'], 'Masks balances on the dashboard and wallet until you turn this off.') . '<h3>Notifications</h3>' . $cb('n_login', 'Login and new-device alerts', (int)$u['notify_login']) . $cb('n_tx', 'Payments and transfers', (int)$u['notify_transaction']) . $cb('n_rem', 'Bills, IOUs and invoice reminders', (int)$u['notify_reminder']) . '<h3>Simulated biometric</h3>' . $cb('bio', 'Allow "simulated biometric" confirmation for small, low-risk payments', (int)$u['sim_biometric'], 'SIMULATION ONLY. It is a button, not fingerprint or face recognition, and it provides no real biometric security.') . btn('Save preferences') . '</form><p class="hint">Privacy defaults: recipient emails are masked on confirmations, security alerts cannot be switched off, and receipts are visible only to the two parties and administrators.</p>') . '</div>';
